from typing import List

def findTotalWeight(cans: List[int]) -> int:
    n = len(cans)
    left = list(range(-1, n - 1))
    right = list(range(1, n + 1))
    removed = [False] * n

    def unlink(i):
        removed[i] = True
        if left[i] >= 0:
            right[left[i]] = right[i]
        if right[i] < n:
            left[right[i]] = left[i]

    total = 0
    # remaining cans keep their relative order, so "lightest, then smallest index"
    # is just the order (weight, original index)
    for i in sorted(range(n), key=lambda i: (cans[i], i)):
        if removed[i]:
            continue
        total += cans[i]
        l, r = left[i], right[i]
        unlink(i)
        if l >= 0:
            unlink(l)
        if r < n:
            unlink(r)
    return total
